326	    /**
327	     * Whether this owner is a <em>possible</em> (soft) duplicate of another owner: {@code true} when some
328	     * other owner shares this owner's last name (case-insensitively) and postcode but has a different
329	     * telephone — a near match. Always false for an owner admitted as a declared household member (via
330	     * {@code sharesHousehold}), which is not a suspected duplicate.
331	     * Computed per request, not persisted. See {@link #getPossibleDuplicateOf()} for the matched owner.
332	     */
333	    public Boolean getPossibleDuplicate() {
334	        return this.possibleDuplicate;
335	    }
336	
337	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
338	        this.possibleDuplicate = possibleDuplicate;
339	    }
340	
341	    /**
342	     * The id of the existing owner this owner possibly duplicates (same last name and postcode, different
343	     * telephone), or {@code null} when {@link #getPossibleDuplicate() possibleDuplicate} is false. When
344	     * several owners match, this is the earliest (lowest id). Computed per request, not persisted.
345	     */
346	    public Integer getPossibleDuplicateOf() {
347	        return this.possibleDuplicateOf;
348	    }
349	
350	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
351	        this.possibleDuplicateOf = possibleDuplicateOf;
352	    }
